// State lookup by ID and by Name
const INDIA_STATE_BY_ID = {};
const INDIA_STATE_BY_NAME = {};
INDIA_MAP_DATA.states.forEach(s => {
  INDIA_STATE_BY_ID[s.id] = s;
  INDIA_STATE_BY_NAME[s.name.toLowerCase()] = s;
});

/**
 * Resolves an event (by city/state/name) to an Indian state ID.
 * Returns { id, name, cx, cy } or null if indeterminate / online pan-India.
 */
function resolveEventState(event) {
  if (!event) return null;
  if (event.state && INDIA_STATE_BY_ID[event.state]) {
    return INDIA_STATE_BY_ID[event.state];
  }
  if (event.state && INDIA_STATE_BY_NAME[event.state.toLowerCase()]) {
    return INDIA_STATE_BY_NAME[event.state.toLowerCase()];
  }
  const str = ((event.city || '') + ' ' + (event.name || '') + ' ' + (event.organizer || '')).toLowerCase();
  for (const [kw, sid] of Object.entries(INDIA_STATE_KEYWORDS)) {
    // word boundary check or exact substring match
    const regex = new RegExp('(?:\b|^)' + kw.replace(/[-\/\^+?.()|[\]{}]/g, '\$&') + '(?:\b|$)', 'i');
    if (regex.test(str) || str.includes(kw)) {
      return INDIA_STATE_BY_ID[sid] || null;
    }
  }
  return null;
}

if (typeof window !== 'undefined') {
  window.INDIA_MAP_DATA = INDIA_MAP_DATA;
  window.INDIA_STATE_KEYWORDS = INDIA_STATE_KEYWORDS;
  window.INDIA_STATE_BY_ID = INDIA_STATE_BY_ID;
  window.INDIA_STATE_BY_NAME = INDIA_STATE_BY_NAME;
  window.resolveEventState = resolveEventState;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { INDIA_MAP_DATA, INDIA_STATE_KEYWORDS, INDIA_STATE_BY_ID, INDIA_STATE_BY_NAME, resolveEventState };
}
